 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"built.txt"))return;Directory.CreateDirectory(E);Directory.CreateDirectory(D);var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_TerracedInteriors.unity");File.Copy(scene.path,E+"scene-before.unity.txt",true);var terrain=Object.FindObjectOfType<Terrain>();var player=Object.FindObjectOfType<HunterTorchPose>();var torch=player.GetComponentsInChildren<Light>(true).First(l=>l.name=="Carried lantern");torch.intensity=6.5f;torch.range=13;var clear=torch.GetComponent<SettlementFogLight>();clear.innerRadius=Mathf.Max(clear.innerRadius,1.4f);clear.outerRadius=Mathf.Max(clear.outerRadius,6.5f);clear.referenceIntensity=6.5f;
