 var fire=pit.GetComponentInChildren<Light>(true);fire.enabled=true;fire.transform.localPosition=new Vector3(0,.9f,0);fire.intensity=5;fire.range=12;fire.shadows=UnityEngine.LightShadows.None;var flick=pit.GetComponent<LanternFlicker>();if(flick){flick.enabled=true;flick.source=fire;flick.baseIntensity=5;}var volume=fire.GetComponent<VolumetricAdditionalLight>();if(!volume)volume=fire.gameObject.AddComponent<VolumetricAdditionalLight>();volume.Scattering=.65f;var fog=fire.GetComponent<SettlementFogLight>();if(!fog)fog=fire.gameObject.AddComponent<SettlementFogLight>();fog.source=fire;fog.innerRadius=1.4f;fog.outerRadius=5;fog.referenceIntensity=5;fog.minimumDensity=.15f;
 var fx=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Viking Village/Prefabs/Props/pf_torch_fire_01.prefab"));fx.name="Restored square bonfire FX";fx.transform.SetParent(pit,false);fx.transform.localPosition=new Vector3(0,.25f,0);fx.transform.localRotation=Quaternion.identity;fx.transform.localScale=Vector3.one*1.6f;foreach(var t in fx.GetComponentsInChildren<Transform>(true)){GameObjectUtility.SetStaticEditorFlags(t.gameObject,0);GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);}foreach(var l in fx.GetComponentsInChildren<Light>(true))Object.DestroyImmediate(l.gameObject);foreach(var c in fx.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(c);foreach(var r in fx.GetComponentsInChildren<MeshRenderer>(true))Object.DestroyImmediate(r.gameObject);foreach(var ps in fx.GetComponentsInChildren<ParticleSystem>(true)){ps.gameObject.SetActive(true);ps.transform.localPosition=new Vector3(0,ps.name=="fx_smoke"?.25f:.12f,0);var main=ps.main;main.loop=true;main.playOnAwake=true;main.scalingMode=ParticleSystemScalingMode.Hierarchy;var r=ps.GetComponent<ParticleSystemRenderer>();if(ps.name=="fx_fire")r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Viking Village/Materials/Effects/mat_fx_fire_01.mat");else if(ps.name=="fx_smoke")r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Demo/Characters/Hunter/Torch/Torch_mat_fx_smoke_01.mat");}
