 foreach(var c in npc.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(c);var animator=npc.GetComponent<Animator>();animator.avatar=AssetDatabase.LoadAllAssetsAtPath("Assets/SopaDopa/URP_Medieval_Fantasy/Base_Char_Meshes/Constructor_2_1.fbx").OfType<Avatar>().First(a=>a.isValid&&a.isHuman);animator.applyRootMotion=false;var ctrl=AnimatorController.CreateAnimatorControllerAtPath(AssetDatabase.GenerateUniqueAssetPath(D+"Villager_Idle.controller"));var idle=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Demo/Characters/Hunter/Idle.anim");ctrl.layers[0].stateMachine.AddState("Idle").motion=idle;animator.runtimeAnimatorController=ctrl;
 string prefab=AssetDatabase.GenerateUniqueAssetPath(D+"NPC_Villager_Witness_Candidate.prefab");PrefabUtility.SaveAsPrefabAsset(npc,prefab);var witness=Object.FindObjectsOfType<DemoInteractable>().First(c=>c.clueId=="witness");foreach(var r in witness.GetComponentsInChildren<Renderer>(true))r.enabled=false;npc.transform.SetParent(witness.transform,false);npc.transform.localPosition=Vector3.zero;npc.transform.localRotation=Quaternion.Euler(0,180,0);witness.gameObject.AddComponent<VillagerCandidateProbe>();EditorSceneManager.SaveScene(scene);
 var review=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(review);var preview=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(prefab));preview.AddComponent<VillagerCandidateProbe>().review=true;var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.SetColor("_BaseColor",new Color(.14f,.15f,.14f));AssetDatabase.CreateAsset(fm,D+"ReviewFloor.mat");floor.GetComponent<Renderer>().sharedMaterial=fm;var camera=new GameObject("NPC Review Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(0,1.15f,3.8f);camera.transform.LookAt(Vector3.up*1.05f);camera.fieldOfView=38;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.06f,.07f,.07f);preview.transform.rotation=Quaternion.identity;var key=new GameObject("Review key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.6f;key.transform.rotation=Quaternion.Euler(40,155,0);var fill=new GameObject("Review fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.7f;fill.transform.rotation=Quaternion.Euler(25,-40,0);RenderSettings.ambientLight=new Color(.4f,.4f,.4f);string reviewPath=AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Scenes/NPCVillagerReview.unity");EditorSceneManager.SaveScene(review,reviewPath);EditorSceneManager.CloseScene(review,true);SceneManager.SetActiveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(E+"built.txt","world="+scene.path+"\nreview="+reviewPath+"\nprefab="+prefab+"\nTorch 3.5/9 -> 6.5/13; fog clear >=1.4/6.5m. Bonfire restored with 3 loop effects + flicker light + volume/fog.\nAvatar valid="+animator.avatar.isValid+" human="+animator.avatar.isHuman+" idle="+(idle?idle.name:"MISSING")+"\n"+report);}
